package com.projectsale.api.auth.service;
import static com.projectsale.api.auth.dto.AuthDtos.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import com.projectsale.api.auth.entity.RefreshToken; import com.projectsale.api.auth.mapper.UserMapper; import com.projectsale.api.auth.repository.RefreshTokenRepository; import com.projectsale.api.auth.security.*; import com.projectsale.api.common.exception.AppException; import com.projectsale.api.user.entity.*; import com.projectsale.api.user.repository.UserRepository; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.security.crypto.password.PasswordEncoder;
class AuthServiceTest {
 private UserRepository users;private RefreshTokenRepository tokens;private JwtService jwt;private UserMapper mapper;private AuthService service;
 @BeforeEach void setup(){users=mock(UserRepository.class);tokens=mock(RefreshTokenRepository.class);jwt=mock(JwtService.class);mapper=mock(UserMapper.class);service=new AuthService(users,tokens,mock(PasswordEncoder.class),jwt,new JwtProperties("unused","i","a",Duration.ofMinutes(15),Period.ofDays(30),Duration.ZERO),mapper);when(tokens.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void refreshRotatesCurrentToken(){User user=mock(User.class);when(user.isActive()).thenReturn(true);RefreshToken current=mock(RefreshToken.class);UUID family=UUID.randomUUID();when(current.usableAt(any())).thenReturn(true);when(current.getUser()).thenReturn(user);when(current.getTokenFamilyId()).thenReturn(family);when(tokens.findForUpdate(anyString())).thenReturn(Optional.of(current));when(jwt.issue(user)).thenReturn("jwt");RefreshResponse response=service.refresh(new RefreshRequest("old"));assertThat(response.accessToken()).isEqualTo("jwt");assertThat(response.refreshToken()).isNotBlank();verify(current).rotateTo(any(RefreshToken.class),any());}
 @Test void reusedTokenRevokesFamily(){RefreshToken current=mock(RefreshToken.class);UUID family=UUID.randomUUID();when(current.usableAt(any())).thenReturn(false);when(current.getTokenFamilyId()).thenReturn(family);when(tokens.findForUpdate(anyString())).thenReturn(Optional.of(current));assertThatThrownBy(()->service.refresh(new RefreshRequest("old"))).isInstanceOf(AppException.class);verify(tokens).revokeFamily(eq(family),any());}
}
